import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.DZhUhjDB.js";const m=JSON.parse('{"title":"09 — Cómo seguir este repo a partir de aquí","description":"","frontmatter":{"title":"09 — Cómo seguir este repo a partir de aquí"},"headers":[],"relativePath":"modules/fundamentos/09-como-seguir-este-repo.md","filePath":"modules/fundamentos/09-como-seguir-este-repo.md","lastUpdated":1787529976000}'),i={name:"modules/fundamentos/09-como-seguir-este-repo.md"};function d(s,e,c,l,n,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_09-—-como-seguir-este-repo-a-partir-de-aqui" tabindex="-1">09 — Cómo seguir este repo a partir de aquí</h1><blockquote><p>🎯 <strong>Objetivo:</strong> una vez leída la base, saber qué carpeta abrir según lo que te interese o lo que necesites profundizar. Este archivo es tu mapa.</p></blockquote><h2 id="¿que-has-hecho-ya" tabindex="-1">¿Qué has hecho ya?</h2><p>Si vienes de los archivos anteriores de esta carpeta, ya tienes:</p><ul><li>✅ Idea general del campo y los roles</li><li>✅ Glosario para no perderte con la jerga</li><li>✅ Conceptos de redes</li><li>✅ Manejo básico de Linux y Windows</li><li>✅ Criptografía fundamental</li><li>✅ Cómo se clasifican las vulnerabilidades</li><li>✅ Ética y marco legal</li><li>✅ Lista de herramientas clave</li></ul><p>Ya puedes leer cualquier parte del repo sin sentirte perdido.</p><h2 id="🔀-¿que-te-interesa" tabindex="-1">🔀 ¿Qué te interesa?</h2><p>Elige una de las 4 rutas siguientes y abre su archivo:</p><h3 id="🛡️-si-te-gusta-defender" tabindex="-1">🛡️ Si te gusta defender</h3><p>→ <a href="./rutas/ruta-defensor"><code>rutas/ruta-defensor.md</code></a></p><p>Quiero entender al atacante para defender mejor: → <a href="./rutas/ruta-atacante"><code>rutas/ruta-atacante.md</code></a></p><h3 id="🤖-si-te-interesa-la-ia" tabindex="-1">🤖 Si te interesa la IA</h3><p>→ <a href="./rutas/ruta-ai-security"><code>rutas/ruta-ai-security.md</code></a></p><h3 id="🧪-si-quieres-practicar-primero" tabindex="-1">🧪 Si quieres practicar primero</h3><p>→ Salta directamente a <a href="./../04-LABORATORIOS/"><code>../04-LABORATORIOS/</code></a></p><h2 id="📚-recursos-complementarios-al-margen-de-las-rutas" tabindex="-1">📚 Recursos complementarios al margen de las rutas</h2><table tabindex="0"><thead><tr><th>Si quieres…</th><th>Abre esto</th></tr></thead><tbody><tr><td>Certificaciones</td><td><a href="./../05-RECURSOS/certificaciones/"><code>../05-RECURSOS/certificaciones/</code></a></td></tr><tr><td>Cursos recomendados</td><td><a href="./../05-RECURSOS/cursos-recomendados/"><code>../05-RECURSOS/cursos-recomendados/</code></a></td></tr><tr><td>Libros</td><td><a href="./../05-RECURSOS/libros/"><code>../05-RECURSOS/libros/</code></a></td></tr><tr><td>Cheatsheets</td><td><a href="./../05-RECURSOS/cheatsheets/"><code>../05-RECURSOS/cheatsheets/</code></a></td></tr><tr><td>Roadmap del proyecto</td><td><a href="./../ROADMAP"><code>../ROADMAP.md</code></a></td></tr><tr><td>Módulos / estructura</td><td><a href="./../MODULOS"><code>../MODULOS.md</code></a></td></tr><tr><td>Currículum formativo</td><td><a href="./../CURRICULUM"><code>../CURRICULUM.md</code></a></td></tr><tr><td>Rutas del repo</td><td><a href="./../RUTAS"><code>../RUTAS.md</code></a></td></tr></tbody></table><h2 id="🤝-contribuir" tabindex="-1">🤝 Contribuir</h2><p>Encontraste un error en la base?¿Falta algo?¿Quieres mejorar un archivo?</p><ul><li>Abre un issue describiendo el cambio.</li><li>O manda un PR directamente.</li><li>También mira <a href="./../CONTRIBUIR"><code>../CONTRIBUIR.md</code></a> y <a href="./../TEMPLATE-MODULO"><code>../TEMPLATE-MODULO.md</code></a>.</li></ul><h2 id="🗺️-¿y-el-sitio-web-publicado" tabindex="-1">🗺️ ¿Y el sitio web publicado?</h2><p>Hay un sitio en GitHub Pages montado con todo este contenido, en <a href="./../docs/"><code>../docs/</code></a>. Allí encontrarás:</p><ul><li><code>index.html</code> — landing</li><li><code>app.html</code> — aplicación</li><li><code>herramientas.html</code>, <code>recursos.html</code>, <code>labs.html</code>, <code>retos.html</code></li><li><code>modules/</code> — los mismos módulos del repo raíz, navegables como web</li></ul><p>Cuando un PR mergea, el sitio se regenera automáticamente.</p><h2 id="✏️-ejercicio-final" tabindex="-1">✏️ Ejercicio final</h2><ol><li>Cierra esta carpeta.</li><li>Elige una ruta en <a href="./"><code>./rutas/</code></a>.</li><li>Lee su archivo completo y abre las carpetas que te sugiere.</li><li>Programa al menos 1 hora para practicar en un lab esa semana.</li></ol><hr><blockquote><p>💡 <strong>Recordatorio final:</strong> la base no se aprende de una vez. Vuelve aquí cada vez que un módulo te deje con dudas. La repetición espaciada funciona.</p></blockquote>',28)])])}const h=a(i,[["render",d]]);export{m as __pageData,h as default};
